def transform_rule_at_least_2(grid):
    """
    Rule: For a diagonal pair of same values, fill a direction only if 
    that direction can fill AT LEAST 2 cells in background.
    If only 0 or 1 cells are available, don't fill (even if bg).
    """
    rows, cols = len(grid), len(grid[0])
    bg = grid[0][0]

    from collections import defaultdict
    positions = defaultdict(list)
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != bg:
                positions[v].append((r, c))

    result = [[bg] * cols for _ in range(rows)]

    # Copy original non-background cells
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != bg:
                result[r][c] = v

    # Extend diagonals
    for v, pos_list in positions.items():
        if len(pos_list) < 2:
            continue

        pos_list = sorted(pos_list)
        pos1, pos2 = pos_list[0], pos_list[1]
        r1, c1 = pos1
        r2, c2 = pos2

        dr, dc = r2 - r1, c2 - c1
        if dr == 0 or dc == 0 or abs(dr) != abs(dc):
            continue

        step_r = 1 if dr > 0 else -1
        step_c = 1 if dc > 0 else -1

        # Check how many cells can be filled backward from pos1
        backward_count = 0
        r, c = r1, c1
        while True:
            nr, nc = r - step_r, c - step_c
            if not 0 <= nr < rows or not 0 <= nc < cols:
                break
            if result[nr][nc] != bg:
                break
            backward_count += 1
            r, c = nr, nc

        # Check how many cells can be filled forward from pos2
        forward_count = 0
        r, c = r2, c2
        while True:
            nr, nc = r + step_r, c + step_c
            if not 0 <= nr < rows or not 0 <= nc < cols:
                break
            if result[nr][nc] != bg:
                break
            forward_count += 1
            r, c = nr, nc

        print(f"Value {v}: backward_count={backward_count}, forward_count={forward_count}")

        # Fill backward only if count >= 2
        if backward_count >= 2 or (backward_count >= 1 and backward_count <= 1):
            # Actually, let me try: fill if count >= 2
            if backward_count >= 2:
                r, c = r1, c1
                while True:
                    nr, nc = r - step_r, c - step_c
                    if not 0 <= nr < rows or not 0 <= nc < cols:
                        break
                    if result[nr][nc] != bg:
                        break
                    result[nr][nc] = v
                    r, c = nr, nc
        else:
            # Try single cell fill
            r, c = r1, c1
            while True:
                nr, nc = r - step_r, c - step_c
                if not 0 <= nr < rows or not 0 <= nc < cols:
                    break
                if result[nr][nc] != bg:
                    break
                result[nr][nc] = v
                r, c = nr, nc

        # Fill forward only if count >= 2
        if forward_count >= 2:
            r, c = r2, c2
            while True:
                nr, nc = r + step_r, c + step_c
                if not 0 <= nr < rows or not 0 <= nc < cols:
                    break
                if result[nr][nc] != bg:
                    break
                result[nr][nc] = v
                r, c = nr, nc
        else:
            # Try single cell fill
            r, c = r2, c2
            while True:
                nr, nc = r + step_r, c + step_c
                if not 0 <= nr < rows or not 0 <= nc < cols:
                    break
                if result[nr][nc] != bg:
                    break
                result[nr][nc] = v
                r, c = nr, nc

    return result

